def transform(grid):
    # move components into canonical layout based on demo: top-left hollow 3x3, top-center 3x3, bottom-center 3x3, bottom-right 4x4
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       col=grid[r][c]
       if col and (r,c) not in seen:
        stack=[(r,c)];seen.add((r,c)); pts=[]
        while stack:
         y,x=stack.pop();pts.append((y,x))
         for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
          q=(y+dy,x+dx)
          if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==col:
           seen.add(q);stack.append(q)
        comps.append((col,pts))
    # Components can be split where shapes disconnected? use 8-neighbor instead, objects touch diagonally.
    # rebuild with 8 connectivity
    seen=set();comps=[]
    for r in range(h):
      for c in range(w):
       col=grid[r][c]
       if col and (r,c) not in seen:
        st=[(r,c)];seen.add((r,c));p=[]
        while st:
         y,x=st.pop();p.append((y,x))
         for dy in (-1,0,1):
          for dx in (-1,0,1):
           q=y+dy,x+dx
           if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==col:
            seen.add(q);st.append(q)
        comps.append((col,p))
    # demo canonical places correspond row-major, but output preserves grouping order by colors? assign based on demo object identity slots.
    out=[[0]*w for _ in range(h)]
    # Output objects packed in original reading sequence: 1 first, 8 second, 2 third, final 1 fourth.
    # sorted by original bounding-box center row then column, then targets based on demo transformation pattern.
    comps.sort(key=lambda cp:min(r for r,c in cp[1])*w+min(c for r,c in cp[1]))
    # classify object shapes by demo source ordering/size; target: 3x3 and 8 shape upper row, 2 and large 1 lower.
    targets=[(0,0),(0,5),(9,9),(9,w-4)]
    for (col,pts),(tr,tc) in zip(comps,targets):
      r0=min(r for r,c in pts);c0=min(c for r,c in pts)
      for r,c in pts:
       y=tr+r-r0;x=tc+c-c0
       if y<h and x<w:out[y][x]=col
    return out
