    for r in range(h):
      for c in range(w):
       col=grid[r][c]
       if not col or (r,c) in seen: continue
       st=[(r,c)];seen.add((r,c));p=[]
       while st:
        y,x=st.pop();p.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         q=(y+dy,x+dx)
         if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==col:
          seen.add(q);st.append(q)
       r0=min(y for y,x in p);r1=max(y for y,x in p);c0=min(x for y,x in p);c1=max(x for y,x in p)
       empty={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if (y,x) not in set(p)}
       edge={(y,x) for y,x in empty if y in (r0,r1) or x in (c0,c1)}
       outside=set(edge);todo=list(edge)
       while todo:
        y,x=todo.pop()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         q=y+dy,x+dx
         if q in empty and q not in outside: outside.add(q);todo.append(q)
       closed=bool(empty-outside)
       objs.append((col,p,closed))
    # Move closed shapes upward and open shapes downward, without changing their columns.
    # Process in source order; each object slides until boundary or another object.
    objs.sort(key=lambda o:min(y for y,x in o[1]))
    placed=[]
    for col,p,closed in objs:
      dy=-1 if closed else 1
      while True:
       q={(y+dy,x) for y,x in p}
       if min(y for y,x in q)<0 or max(y for y,x in q)>=h or any(q & pp for _,pp in placed): break
       p=[(y+dy,x) for y,x in p]
      placed.append((col,set(p)))
    out=[[0]*w for _ in range(h)]
    for col,p in placed:
     for y,x in p:out[y][x]=col
    return out
