def transform(grid):
    h,w=len(grid),len(grid[0]);seen=set();objs=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if not col or (r,c) in seen: continue
            st=[(r,c)];seen.add((r,c));pts=[]
            while st:
                y,x=st.pop();pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
