    for up in (True,False):
        group=[o for o in objs if (sum(y for y,x in o[1])/len(o[1]) < h/2)==up]
        group.sort(key=lambda o:min(y for y,x in o[1]) if up else -max(y for y,x in o[1]))
        dy=-1 if up else 1
        for col,p in group:
            while True:
                q={(y+dy,x) for y,x in p}
                if min(y for y,x in q)<0 or max(y for y,x in q)>=h or any(q & pp for _,pp in placed): break
                p={(y+dy,x) for y,x in p}
            placed.append((col,p))
    out=[[0]*w for _ in range(h)]
    for col,p in placed:
        for y,x in p:out[y][x]=col
    return out
